// convertReq wraps a fixture payload + query into a ConvertRequest. Fixtures
// mirror the real shikimori v1 payloads (score is a decimal string; url/image
// are relative paths). No I/O.
func convertReq(t *testing.T, payload string, query map[string]any) *metadatav1.ConvertRequest {
	t.Helper()
	req := &metadatav1.ConvertRequest{RawResponse: []byte(payload)}
	if query != nil {
		q, err := structpb.NewStruct(query)
		if err != nil {
			t.Fatalf("fixture query struct: %v", err)
		}
		req.Query = q
	}
	return req
}

// byIDPayload is a minimal by-id anime answer (the anchored run's primary
// body) reused by the cast subtests; a list variant covers the search run.
const (
	byIDPayload = `{
		"id": 1, "name": "Air", "russian": "Воздух",
		"kind": "tv", "status": "released", "episodes": 13,
		"url": "/animes/1-air"
	}`
	listPayload = `[
		{"id": 1, "name": "Air", "kind": "tv", "episodes": 13, "aired_on": "2005-01-06"}
	]`
)

// TestConvert drives Convert over the fixture payloads (box 1.3): the by-id
// single-object namespace shape, the multi-candidate selection (preference
// score + nothing-agrees determinism), the empty result, and the provenance
// hints.
func TestConvert(t *testing.T) {
	p := &sourceImpl{}

	t.Run("by-id payload fills the RU-first namespace", func(t *testing.T) {
		payload := `{
			"id": 1, "name": "Cowboy Bebop", "russian": "Ковбой Бибоп",
			"kind": "tv", "status": "released", "score": "8.542",
			"episodes": 26, "aired_on": "1998-04-03",
			"description": "В 2071 году...",
			"url": "/animes/1-cowboy-bebop",
			"image": {"original": "/images/anime/original/1.jpg"},
			"genre": [{"name": "Adventure", "russian": "Приключения"},
			          {"name": "Sci-Fi", "russian": "Фантастика"}]
		}`
		res, err := p.Convert(context.Background(), convertReq(t, payload, nil))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		meta := res.GetMetadata().AsMap()
		title, _ := meta["title"].(map[string]any)
		if title["romaji"] != "Cowboy Bebop" || title["russian"] != "Ковбой Бибоп" {
			t.Errorf("title = %v, want {romaji, russian}", title)
		}
		for k, want := range map[string]any{
			"kind":        "tv",
			"status":      "released",
			"score":       8.542,
			"episodes":    float64(26),
			"aired_on":    "1998-04-03",
			"description": "В 2071 году...",
			"url":         "https://shikimori.io/animes/1-cowboy-bebop",
			"poster":      "https://shikimori.io/images/anime/original/1.jpg",
		} {
			if meta[k] != want {
				t.Errorf("meta[%q] = %v, want %v", k, meta[k], want)
			}
		}
		genres, _ := meta["genres"].([]any)
		if len(genres) != 2 || genres[0] != "Приключения" || genres[1] != "Фантастика" {
			t.Errorf("genres = %v, want the RU-first names", genres)
		}
		ids, _ := meta[resolvedIDsKey].(map[string]any)
		if ids[idKey] != float64(1) {
			t.Errorf("resolved_ids = %v, want {shikimori_id: 1}", ids)
		}
		for field, hint := range res.GetProvenance() {
			if hint.GetPluginId() != pluginID || hint.GetPluginVersion() != pluginVersion {
				t.Errorf("provenance[%q] = %s@%s, want %s@%s", field,
					hint.GetPluginId(), hint.GetPluginVersion(), pluginID, pluginVersion)
			}
			if hint.GetSourceUrl() != "https://shikimori.io/animes/1-cowboy-bebop" {
				t.Errorf("provenance[%q].source_url = %q, want the anime URL", field, hint.GetSourceUrl())
			}
		}
	})

	t.Run("multi-candidate search prefers year kind and episode agreement", func(t *testing.T) {
		payload := `[
			{"id": 10, "name": "Wrong Series", "kind": "tv", "episodes": 26, "aired_on": "1996-01-01"},
			{"id": 20, "name": "Perfect Blue", "russian": "Идеальная грусть", "kind": "movie",
			 "episodes": 1, "aired_on": "1997-08-05", "url": "/animes/20-perfect-blue"},
			{"id": 30, "name": "Other Movie", "kind": "movie", "episodes": 1, "aired_on": "1999-02-17"}
		]`
		query := map[string]any{"title": "Perfect Blue", "kind": "movie", "year": int64(1997), "episodes": int64(1)}
		res, err := p.Convert(context.Background(), convertReq(t, payload, query))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		meta := res.GetMetadata().AsMap()
		ids, _ := meta[resolvedIDsKey].(map[string]any)
		if got := ids[idKey]; got != float64(20) {
			t.Fatalf("selected candidate id = %v, want 20 (year + kind + episodes agree)", got)
		}
		if got := res.GetMetadata().AsMap()["title"].(map[string]any)["romaji"]; got != "Perfect Blue" {
			t.Errorf("selected title.romaji = %q, want Perfect Blue", got)
		}
	})

	t.Run("nothing agreeing still selects deterministically without error", func(t *testing.T) {
		payload := `[
			{"id": 10, "name": "First", "kind": "tv", "episodes": 12, "aired_on": "2001-01-01"},
			{"id": 20, "name": "Second", "kind": "tv", "episodes": 24, "aired_on": "2002-01-01"}
		]`
		res, err := p.Convert(context.Background(), convertReq(t, payload, map[string]any{"title": "First"}))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("nothing-agrees selection errored: %v", res.GetError())
		}
		meta := res.GetMetadata().AsMap()
		ids, _ := meta[resolvedIDsKey].(map[string]any)
		if got := ids[idKey]; got != float64(10) {
			t.Fatalf("selected candidate id = %v, want 10 (upstream order breaks ties)", got)
		}
	})

	t.Run("empty result list is a recorded soft error", func(t *testing.T) {
		res, err := p.Convert(context.Background(), convertReq(t, `[]`, map[string]any{"title": "Х"}))
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() == nil || res.GetError().GetCode() != "upstream_empty" {
			t.Fatalf("error = %v, want code upstream_empty", res.GetError())
		}
		if len(res.GetMetadata().GetFields()) != 0 {
			t.Errorf("metadata = %v, want empty on a soft error", res.GetMetadata().AsMap())
		}
	})

	t.Run("roles extra response composes the convention cast", func(t *testing.T) {
		rolesPayload := `[
			{"id": 448, "name": "Misuzu Kamio", "russian": "Мисудзу Камио",
			 "image": {"original": "/images/characters/448.jpg"}, "roles": ["Main"],
			 "seyu": [{"id": 522, "name": "Asami Sanada", "russian": "Асами Санада"}]},
			{"id": 451, "name": "Yukito Kunisaki", "russian": "Юкито Кунисаки",
			 "image": {"original": "/images/characters/451.jpg"}, "roles": ["Main"], "seyu": []},
			{"id": 460, "name": "No Portrait", "russian": "Без Портрета"},
			{"image": {"original": "/images/characters/999.jpg"},
			 "seyu": [{"name": "Unnamed Voice"}]},
			{"id": 470, "name": "Multi Credit", "russian": "Много Голосов",
			 "image": {"original": "/images/characters/470.jpg"},
			 "seyu": [{"name": "First Va", "russian": "Первый Сэйю"}, {"name": "Second Va"}]}
		]`
		req := convertReq(t, byIDPayload, nil)
		req.ExtraResponses = []*metadatav1.FetchedResponse{
			{Fetched: true, HttpStatus: 200, Body: []byte(rolesPayload)},
		}
		res, err := p.Convert(context.Background(), req)
		if err != nil {
			t.Fatalf("Convert: %v", err)
		}
		if res.GetError() != nil {
			t.Fatalf("unexpected Convert error: %v", res.GetError())
		}
		cast, ok := res.GetMetadata().AsMap()[castKey].([]any)
		if !ok || len(cast) != 4 {
			t.Fatalf("cast = %v (ok=%v), want 4 usable entries (the nameless entry skipped)", cast, ok)
		}
		e0, e1, e2, e3 := cast[0].(map[string]any), cast[1].(map[string]any), cast[2].(map[string]any), cast[3].(map[string]any)
		if e0["name"] != "Мисудзу Камио" || e0["role"] != "Асами Санада" ||
			e0["photo_url"] != "https://shikimori.io/images/characters/448.jpg" {
			t.Errorf("cast[0] = %v, want the russian character name, the seiyuu credit and the absolute portrait", e0)
		}
		if e1["name"] != "Юкито Кунисаки" || e1["role"] != nil {
			t.Errorf("cast[1] = %v, want no role when the character has no seiyuu credit", e1)
		}
		if e2["name"] != "Без Портрета" || e2["photo_url"] != nil || e2["role"] != nil {
			t.Errorf("cast[2] = %v, want the optional keys ABSENT when the upstream omits them", e2)
		}
		if e3["role"] != "Первый Сэйю, Second Va" {
			t.Errorf("cast[3].role = %v, want the comma-joined russian-preferred credits", e3["role"])
		}
		if _, has := res.GetProvenance()[castKey]; !has {
			t.Errorf("provenance carries no %q hint, want one like every namespace field", castKey)
		}
	})

	t.Run("missing unfetched or unusable roles leave cast absent", func(t *testing.T) {
		fetchedRoles := func(body string) []*metadatav1.FetchedResponse {
			return []*metadatav1.FetchedResponse{{Fetched: true, HttpStatus: 200, Body: []byte(body)}}
		}
		for _, tc := range []struct {
			name    string
			payload string
			extras  []*metadatav1.FetchedResponse
		}{
			{"no extra responses at all", byIDPayload, nil},
			{"soft-failed extra carries no body", byIDPayload,
				[]*metadatav1.FetchedResponse{{Fetched: false, Error: "connection refused"}}},
			{"empty roles array", byIDPayload, fetchedRoles(`[]`)},
			{"unparsable roles body", byIDPayload, fetchedRoles(`{"error":"not found"}`)},
			{"no usable entries", byIDPayload, fetchedRoles(`[{"seyu": [{"name": "X"}]}]`)},
			{"search list payload stays castless", listPayload, nil},
		} {
			t.Run(tc.name, func(t *testing.T) {
				req := convertReq(t, tc.payload, nil)
				req.ExtraResponses = tc.extras
				res, err := p.Convert(context.Background(), req)
				if err != nil {
					t.Fatalf("Convert: %v", err)
				}
				if got := res.GetError(); tc.payload == byIDPayload && got != nil {
					t.Fatalf("unexpected Convert error: %v", got)
				}
				meta := res.GetMetadata().AsMap()
				if cast, has := meta[castKey]; has {
					t.Errorf("meta[%q] = %v, want the field ABSENT (honest absence, never an empty array)", castKey, cast)
				}
			})
		}
	})
}

// TestMerge pins the namespace write (box 1.3): Merge writes ONLY
// sources["shikimori"], strips the reserved resolved_ids entry (core-side
// identifier input, never a namespace field), and binds every surviving field
// in the view proposal.
func TestMerge(t *testing.T) {
	p := &sourceImpl{}
	incoming, err := structpb.NewStruct(map[string]any{
		"title":        map[string]any{"romaji": "Cowboy Bebop", "russian": "Ковбой Бибоп"},
		"kind":         "tv",
		resolvedIDsKey: map[string]any{idKey: int64(1)},
	})
	if err != nil {
		t.Fatalf("fixture incoming struct: %v", err)
	}
	res, err := p.Merge(context.Background(), &metadatav1.MergeRequest{Incoming: incoming, PluginId: pluginID})
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	data := res.GetDocument().GetData().AsMap()
	if len(data) != 1 {
		t.Fatalf("document top-level keys = %v, want exactly {sources} (INV-namespace-write)", data)
	}
	sources, _ := data["sources"].(map[string]any)
	ns, _ := sources[pluginID].(map[string]any)
	if _, has := ns[resolvedIDsKey]; has {
		t.Errorf("sources.%s carries reserved %s, want it stripped for doc.identifiers", pluginID, resolvedIDsKey)
	}
	if ns["kind"] != "tv" {
		t.Errorf("sources.%s.kind = %v, want tv", pluginID, ns["kind"])
	}
	for _, vb := range res.GetView() {
		if vb.GetSource() != pluginID {
			t.Errorf("view[%q].source = %q, want %q", vb.GetFieldPath(), vb.GetSource(), pluginID)
		}
	}
}
